import { expect, test } from 'bun:test';
import { TokenBucket } from './src/rateLimiter';

test('TokenBucket allows consuming tokens up to capacity', () => {
  const bucket = new TokenBucket(3, 1);
  expect(bucket.tryConsume(1)).toBe(true);
  expect(bucket.tryConsume(1)).toBe(true);
  expect(bucket.tryConsume(1)).toBe(true);
  expect(bucket.tryConsume(1)).toBe(false);
});

test('TokenBucket refills tokens over time', async () => {
  const bucket = new TokenBucket(2, 10);
  expect(bucket.tryConsume(2)).toBe(true);
  expect(bucket.tryConsume(1)).toBe(false);
  await new Promise((r) => setTimeout(r, 120));
  expect(bucket.tryConsume(1)).toBe(true);
});
